/bin/zsh -lc "cat > tb.sv <<'EOF'
"'`timescale 1ns/1ps
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire [5:0] second;
  wire [5:0] minute;

  TopModule dut(.clk(clk), .rst_n(rst_n), .second(second), .minute(minute));

  always #5 clk = ~clk;

  initial begin
    $display("time clk rst_n minute second");
    $monitor("%0t %0b %0b %0d %0d", $time, clk, rst_n, minute, second);
    #2 rst_n = 0;
    #8 rst_n = 1;
    repeat (65) @(posedge clk);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

