/bin/zsh -lc "cat > tb_check.sv <<'EOF'
"'`timescale 1ns/1ps
module tb_check;
  reg clk = 0;
  reg rst_n = 0;
  wire [5:0] second;
  wire [5:0] minute;
  integer cycles;

  TopModule dut(.clk(clk), .rst_n(rst_n), .second(second), .minute(minute));

  always #5 clk = ~clk;

  task expect;
    input [5:0] exp_minute;
    input [5:0] exp_second;
    input [255:0] msg;
    begin
      if (minute !== exp_minute || second !== exp_second) begin
        $display("FAIL %s got minute=%0d second=%0d expected minute=%0d second=%0d", msg, minute, second, exp_minute, exp_second);
        $finish(1);
      end
    end
  endtask

  initial begin
    @(negedge clk);
    rst_n = 0;
    #1;
    expect(0,0,"async reset");

    @(negedge clk);
    rst_n = 1;

    @(posedge clk); #1; expect(0,1,"first second");

    for (cycles = 1; cycles < 60; cycles = cycles + 1)
      @(posedge clk);
    #1; expect(1,1,"first minute rollover");

    for (cycles = 0; cycles < 59*60 - 1; cycles = cycles + 1)
      @(posedge clk);
    #1; expect(60,1,"reach pause minute");

    repeat (5) @(posedge clk);
    #1; expect(60,1,"hold at pause");

    $display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv_check TopModule.sv tb_check.sv && vvp simv_check'

